public sealed class OrdersModel(DbDataSource dataSource) : PageModel
{
    public List<OrderRow> Orders { get; private set; } = new List<OrderRow>();

    public async Task<IActionResult> OnGetAsync(int orderId, CancellationToken cancellationToken)
    {
        await using var command = dataSource.CreateCommand("SELECT Id, ProductName, Quantity, Status FROM OrderLines WHERE OrderId = @orderId");
        var parameter = command.CreateParameter();
        parameter.ParameterName = "@orderId";
        parameter.Value = orderId;
        command.Parameters.Add(parameter);
        using (var reader = await command.ExecuteReaderAsync(cancellationToken))
        {
            while (await reader.ReadAsync(cancellationToken))
            {
                Orders.Add(new OrderRow(
                    reader.GetInt32(0),
                    reader.GetString(1),
                    reader.GetInt32(2),
                    reader.GetString(3)
                ));
            }
        }
        return Page();
    }
}

