public static class DbDataSourceExtensions
{
    public static async Task<IEnumerable<T>> QueryAsync<T>(this DbDataSource dataSource, CommandDefinition command, CancellationToken cancellationToken)
    {
        await using var command = dataSource.CreateCommand(command.CommandText);
        foreach (var parameter in command.Parameters)
        {
            command.Parameters.Add(parameter);
        }
        return await command.QueryAsync<T>(cancellationToken);
    }
}

