using Microsoft.AspNetCore.Mvc.RazorPages;

namespace Migrated.Pages;

public sealed class OrderModel(DbDataSource dataSource) : PageModel
{
    public List<OrderLine> OrderLines { get; private set; } = new List<OrderLine>();

    public async Task<IActionResult> OnGetAsync(int orderId, CancellationToken cancellationToken)
    {
        await using var command = dataSource.CreateCommand("SELECT ProductName, Quantity, Status FROM OrderLines WHERE OrderId = @orderId");
        var parameter = command.CreateParameter();
        parameter.ParameterName = "@orderId";
        parameter.Value = orderId;
        command.Parameters.Add(parameter);
        using (var reader = await command.ExecuteReaderAsync(cancellationToken))
        {
            while (await reader.ReadAsync(cancellationToken))
            {
                OrderLines.Add(new OrderLine(
                    reader.GetString(0),
                    reader.GetInt32(1),
                    reader.GetString(2)
                ));
            }
        }
        return Page();
    }
}

public record OrderLine(string ProductName, int Quantity, string Status);

