using System.Data.Common;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.RazorPages;

namespace Migrated.Pages;

public sealed class ProductSearchModel(DbDataSource dataSource) : PageModel
{
    public string? Keyword { get; private set; }
    public List<ProductRow>? Products { get; private set; }

    public async Task<IActionResult> OnGetAsync(string keyword, CancellationToken cancellationToken)
    {
        Keyword = keyword;
        Products = await GetProductsAsync(keyword, cancellationToken);
        return Page();
    }

    private async Task<List<ProductRow>> GetProductsAsync(string keyword, CancellationToken cancellationToken)
    {
        await using var command = dataSource.CreateCommand("SELECT Id, Name, Price FROM Products WHERE Name LIKE @keyword");
        var parameter = command.CreateParameter();
        parameter.ParameterName = "@keyword";
        parameter.Value = keyword;
        command.Parameters.Add(parameter);
        var products = await command.QueryAsync<ProductRow>(cancellationToken);
        return products.ToList();
    }
}

public record ProductRow(int Id, string Name, decimal Price);

using System.Data.Common;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.RazorPages;

namespace Migrated.Pages;

public sealed class SalesReportModel(DbDataSource dataSource) : PageModel
{
    public string? ReportYear { get; private set; }

    public async Task<IActionResult> OnGetAsync(int reportYear, CancellationToken cancellationToken)
    {
        ReportYear = reportYear.ToString();
        await using var command = dataSource.CreateCommand("SELECT Region, SUM(Amount) AS Total FROM Sales WHERE YEAR(SaleDate) = @reportYear GROUP BY Region");
        var parameter = command.CreateParameter();
        parameter.ParameterName = "@reportYear";
        parameter.Value = reportYear;
        command.Parameters.Add(parameter);
        var regions = (await command.ExecuteReaderAsync(cancellationToken)).ToList<SalesRegion>();

        return View(regions);
    }
}

public record SalesRegion(string Region, decimal Total);
